<?php declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/student_portal.php';$current=tuman_require_role('STUDENT');$credits=tuman_student_credits(tuman_database(),$current['id']);tuman_student_page_start('My credits');?><h1>My credits</h1><p>Credits may be an advance received before an invoice or an overpayment. Your Teacher may apply unused credit to a future invoice or refund it.</p><?php if($credits===[]):?><p>You have no credit balances.</p><?php else:?><table><thead><tr><th>Teacher</th><th>Source</th><th>Currency</th><th>Original credit</th><th>Remaining</th><th>Status</th></tr></thead><tbody><?php foreach($credits as $credit):?><tr><td><?=htmlspecialchars(trim($credit['teacher_first_name'].' '.($credit['teacher_last_name']??'')),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(($credit['source_type']??'OVERPAYMENT')==='ADVANCE'?'Advance':'Overpayment',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($credit['currency_code'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(tuman_invoice_money_label($credit['original_amount'],$credit['currency_code']),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars(tuman_invoice_money_label($credit['remaining_amount'],$credit['currency_code']),ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($credit['status'],ENT_QUOTES,'UTF-8')?></td></tr><?php endforeach;?></tbody></table><?php endif;tuman_student_page_end();?>
